// scripts/gen-ios-assets.mjs
//
// Generates the iOS app icon + splash images for the Greek Stack Capacitor app
// from the CANONICAL navy seal VECTOR (brand/greekstack-seal.svg) — NOT a raster.
// Writes into the committed-by-CI native project (ios/App/App/Assets.xcassets/...).
// ios/ is gitignored and regenerated by `cap add ios`; the tracked source of
// truth is this script + brand/greekstack-seal.svg.
//
// Why a script (not @capacitor/assets): runs on Windows with the `sharp` we
// already depend on, no extra tooling, and the output is deterministic so the
// committed PNGs regenerate identically. Re-run after a brand refresh:
//   node scripts/gen-ios-assets.mjs
//
// App Store rules baked in:
//   • App icon is 1024x1024, FLATTENED (no alpha) — Apple rejects transparent icons.
//   • Icon corners stay square; iOS applies the rounded mask itself.
//   • Splash is a centered mark on the brand navy, exported at 2732x2732 (the
//     universal Capacitor splash size) so it covers every device/orientation.
//
// This replaces the prior cream navy-temple RASTER (public/brand/greekstack-mark
// -alt.png) the owner flagged as "generic AI slop": the seal is the elevated
// classical temple — columns WITH capitals + bases, gold cornice/medallion/
// architrave/floor, stepped stylobate — rendered crisp from vector.

import sharp from "sharp";
import path from "node:path";
import fs from "node:fs";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

// The canonical navy seal vector. The full tile (#0B1B3A) + ivory temple + gold
// accents is the icon composition; we rasterize at 1024 with high density so
// the edges are crisp.
const SEAL = path.join(root, "brand", "greekstack-seal.svg");
const ICONSET = path.join(root, "ios/App/App/Assets.xcassets/AppIcon.appiconset");
const SPLASHSET = path.join(root, "ios/App/App/Assets.xcassets/Splash.imageset");

// Greek Stack brand navy (matches the seal tile + capacitor.config.ts
// backgroundColor + the boot shell in mobile-shell/index.html).
const NAVY = { r: 11, g: 27, b: 58, alpha: 1 }; // #0B1B3A — the seal tile navy
const GOLD = "#E8B53A";

function svgBuffer() {
  return fs.readFileSync(SEAL);
}

async function buildIcon() {
  const size = 1024;
  // Render the full seal (its own rounded tile is masked by iOS anyway) at high
  // density, flatten onto opaque navy, and strip alpha (App Store requirement).
  const buf = await sharp(svgBuffer(), { density: 384 })
    .resize(size, size, { fit: "contain", background: NAVY })
    .flatten({ background: NAVY })
    .removeAlpha()
    .png()
    .toBuffer();

  await sharp(buf).toFile(path.join(ICONSET, "AppIcon-512@2x.png"));
  console.log("✓ AppIcon-512@2x.png (1024x1024, no alpha) from greekstack-seal.svg");
}

async function buildSplash() {
  const size = 2732;
  const markSize = Math.round(size * 0.26); // ~710px centered mark
  // For the splash, render the seal tile small and centered on the brand navy
  // so the icon floats cleanly (no white frame — the seal has none).
  const mark = await sharp(svgBuffer(), { density: 256 })
    .resize(markSize, markSize, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png()
    .toBuffer();
  const offset = Math.round((size - markSize) / 2);

  const buf = await sharp({
    create: { width: size, height: size, channels: 4, background: NAVY },
  })
    .composite([{ input: mark, top: offset, left: offset }])
    .flatten({ background: NAVY })
    .removeAlpha()
    .png()
    .toBuffer();

  // Capacitor's Splash.imageset references three identical universal entries.
  for (const name of [
    "splash-2732x2732.png",
    "splash-2732x2732-1.png",
    "splash-2732x2732-2.png",
  ]) {
    await sharp(buf).toFile(path.join(SPLASHSET, name));
  }
  console.log("✓ Splash 2732x2732 (x3 universal entries)");
}

await buildIcon();
await buildSplash();
console.log("Done. Brand:", GOLD, "on", "#0B1B3A");
